async (cursor, num, params) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const asst = () => [...document.querySelectorAll('[data-message-author-role="assistant"]')];
  const busy = () => !!document.querySelector('[data-testid="stop-button"]');
  if (!cursor) {
    let pm = null;
    for (let i = 0; i < 30 && !(pm = document.querySelector('#prompt-textarea')); i++) await sleep(300);
    if (!pm) throw new Error('[chatgpt-chat] 没找到输入框 #prompt-textarea url=' + location.pathname + location.search);
    if (asst().length) throw new Error('[chatgpt-chat] 入口页上已经有回复——这不是一条新对话');
    const dt = new DataTransfer();
    dt.setData('text/plain', params.prompt);
    pm.focus();
    pm.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true }));
    let send = null;
    const t0 = Date.now();
    while (Date.now() - t0 < 15000) {
      send = document.querySelector('[data-testid="send-button"]');
      if (send && !send.disabled) break;
      await sleep(300);
    }
    if (!send || send.disabled) throw new Error('[chatgpt-chat] 粘贴后 15s 发送按钮仍不可用（输入框字数 ' + pm.textContent.length + '）');
    const sent = () => document.querySelectorAll('[data-message-author-role="user"]').length > 0 || busy();
    const tries = [
      ['click', () => send.click()],
      ['requestSubmit', () => { const f = send.closest('form'); if (f) f.requestSubmit(send); }],
      ['enter', () => pm.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true }))],
    ];
    const used = [];
    for (const [name, fire] of tries) {
      used.push(name);
      fire();
      for (let i = 0; i < 10 && !sent(); i++) await sleep(300);
      if (sent()) break;
    }
    if (!sent()) throw new Error('[chatgpt-chat] 试过 ' + used.join(' / ') + ' 都没把消息发出去（输入框字数 ' + pm.textContent.length + '）');
    window.__cgSentBy = used.at(-1);
    window.__cgT0 = Date.now();
    window.__cgSeenBusy = false;
  }
  const deadline = Math.min(Date.now() + 22000, pageStart + 26000);
  let lastText = null, since = 0;
  while (Date.now() < deadline) {
    const b = busy();
    if (b) window.__cgSeenBusy = true;
    const a = asst().at(-1);
    const txt = a ? ((a.querySelector('.markdown') || a).innerText || '').trim() : '';
    if (a && !b && txt) {
      if (txt === lastText) {
        if (Date.now() - since > 1500) return { items: [{ guid: a.getAttribute('data-message-id') || ('m' + Date.now()), text: txt, model: a.getAttribute('data-message-model-slug') || '' }], cursor: '' };
      } else { lastText = txt; since = Date.now(); }
    }
    await sleep(500);
  }
  const elapsed = Date.now() - (window.__cgT0 || pageStart);
  if (!busy() && !asst().length && elapsed > 30000) {
    const main = (document.querySelector('main') || document.body).innerText.trim().split('\n').filter(Boolean);
    throw new Error('[chatgpt-chat] 发出 ' + Math.round(elapsed / 1000) + 's 后既没在生成、也没有回复（限额 / 报错？）页面末尾: ' + main.slice(-4).join(' / ').slice(0, 300));
  }
  if (elapsed > 300000) throw new Error('[chatgpt-chat] 300s 内没等到完整回复');
  return { items: [], pending: true, cursor: String(Number(cursor || 0) + 1) };
}
